# -*- coding: utf-8 -*-
"""[AI] Soát 70 bài prompt tay tiếng Trung của THE BLOCK CLUB (khuôn viet-prompt-seedance-zh-tay, luật ★ 02/10).
Chép khuôn từ soat_prompt.py của WHEN NOBODY'S WATCHING, đổi nguồn thoại sang 03_kich-ban-chinh-sua.md.

python -X utf8 soat_prompt.py [cụm …]
Kiểm: đủ khối · thoại {…} trùng nguyên văn kịch bản 03 (thứ tự, không ngoặc kép) · câu khoá đúng số câu · mã TÊN（@图片N）
khớp dòng N của .refs · ảnh trong .refs có thật, ≤ 9 · không tên trơn ngoài thoại · mốc giây liền 0–30 · chữ cấm (chung +
Shayna) · độ dài · (cảnh báo) mã trang phục SHEET_ khác dòng Nhân vật của cụm."""
import re, sys
from pathlib import Path

ZH = Path(__file__).resolve().parent
ANH = ZH.parent / 'anh'
GOC = ZH.parents[2]                                             # thư mục tác phẩm
KB = GOC / '03_kich-ban-chinh-sua.md'
TEN = ['TRE', 'AMANI', 'CORNELL', 'MARVA', 'LONNIE', 'EARLINE', 'BLAINE', 'GRANGER', 'GERALD', 'SHAYNA', 'BRIDGES']
KHOI = ['参考图识别说明', '【场景图】', '【人物参考图】', '【人物位置】', '30秒', '镜头语言', '[保持不变]', '结尾时']
NHIEU_ANH = {15, *range(53, 68)}      # 05/11 tác giả: các cụm này chạy model ≥ 6.5¥ (lec-haya-seedance-2-5-xg-720-2, ≤ 30 ảnh)
CAM = ['血', '枪', '杀', '暴力', '性感', '低胸', '胸', '绑架', '伤口']
CAM_SHAYNA = ['乳沟', '露肩', '露脐', '肚脐', '腰', '身材', '曲线', '紧身', '包臀', '迷你', '短裙', '大腿', '臀', '火辣']
HDR = re.compile(r'^CỤM (\d+)\s+\[(\d\d:\d\d)–(\d\d:\d\d)\]\s+(.*?)(?:\s+\[AI-[^\]]*\])?$')
DONG = re.compile(r'^    ([A-Z][A-Z .\'-]*?)(?: \((.*?)\))?: "(.*)$')


def kich_ban():
    """{n: {'thoai': [câu…], 'ma': {TÊN: {mã…}}}} từ 03_kich-ban-chinh-sua.md"""
    ra, cur = {}, None
    for l in KB.read_text(encoding='utf-8').split('\n'):
        m = HDR.match(l)
        if m:
            cur = int(m.group(1)); ra[cur] = []; continue
        if l.startswith(('-' * 100, '=' * 100, '#' * 100, 'HẾT PHIM')): cur = None; continue
        if cur: ra[cur].append(l)
    kq = {}
    for n, L in ra.items():
        th, i = [], 0
        while i < len(L):
            m = DONG.match(L[i])
            if m:
                s, j = m.group(3), i
                while not s.rstrip().endswith('"') and j + 1 < len(L):
                    j += 1; s += ' ' + L[j].strip()
                th.append(s.rstrip()[:-1].strip()); i = j + 1; continue
            i += 1
        txt = '\n'.join(L)
        nv = re.search(r'^Nhân vật: (.*?)(?=^Chức năng:)', txt, re.M | re.S)
        ma = {}
        for t, inside in re.findall(r'\b([A-Z]{3,})\s*\(([^)]*)\)', nv.group(1) if nv else ''):
            ma.setdefault(t, set()).update(re.findall(r'\b([A-Z]{2}\d)\b', inside))
        kq[n] = {'thoai': th, 'ma': ma}
    return kq


def chuan(s):
    return s.replace('’', "'").replace('‘', "'").replace('“', '"').replace('”', '"').replace('…', '...').strip()


def soat(n, kb):
    loi, canh = [], []
    f = ZH / 'prompt' / f'cum_{n:03d}.txt'
    fr = ZH / 'prompt' / f'cum_{n:03d}.refs'
    if not f.exists(): return ['THIẾU bài'], []
    if not fr.exists(): return ['THIẾU .refs'], []
    t = f.read_text(encoding='utf-8-sig')
    refs = [x.strip() for x in fr.read_text(encoding='utf-8-sig').splitlines() if x.strip()]
    toi_da = 30 if n in NHIEU_ANH else 9
    if len(refs) > toi_da: loi.append(f'{len(refs)} ảnh > {toi_da}')
    for r in refs:
        if not (ANH / f'{r}.png').exists(): loi.append(f'không có ảnh {r}.png')
    for k in KHOI:
        if k not in t: loi.append(f'thiếu khối {k}')
    # thoại
    th = [x for x in re.findall(r'\{([^{}]*)\}', t) if not re.fullmatch(r'[^A-Za-z]*', x)]
    for x in th:
        if '"' in x or '“' in x: loi.append(f'thoại còn ngoặc kép: {x[:40]}')
    can = [chuan(x) for x in kb.get(n, {}).get('thoai', [])]
    co = [chuan(x).strip('"') for x in th]
    if co != can:
        loi.append(f'thoại lệch kịch bản: bài {len(co)} câu, kịch bản {len(can)} câu')
        for i, (a, b) in enumerate(zip(co, can)):

