                  r'(?: \(([^)]*)\))?:? "(.*)"\s*$')


def kich_ban():
    """{n: {'thoai': [câu…], 'ma': {TÊN: {mã…}}}} từ 04_kich-ban-chinh-thuc.md"""
    ra, cur = {}, None
    for l in KB.read_text(encoding='utf-8').split('\n'):
        m = HDR.match(l)
        if m:
            cur = int(m.group(1)); ra[cur] = []; continue
        if l.startswith(('### ', '## ', '# ')): cur = None; continue
        if cur: ra[cur].append(l)
    kq = {}
    for n, L in ra.items():
        th = [m.group(3).strip() for l in L if (m := DONG.match(l))]
        txt = '\n'.join(L)
        nv = re.search(r'^\*\*Nhân vật:\*\* (.*)$', txt, re.M)
