        if moc[0][0] != 0 or moc[-1][1] != 30: loi.append(f'mốc không phủ 0–30: {moc[0]}…{moc[-1]}')
        for (a, b), (c, d) in zip(moc, moc[1:]):
            if b != c: loi.append(f'hở/chồng mốc {b}≠{c}')
    for w in CAM:
        if w in ngoai: loi.append(f'chữ cấm {w}')
    if re.search(r'打(?!乱)', ngoai): loi.append('chữ 打')
