        for w in CAM_GOI_CAM:
            if w in ngoai: loi.append(f'chữ cấm (Jordyn/Mya) {w}')
    if '"' in ngoai or '“' in ngoai: canh.append('còn ngoặc kép ngoài thoại')
    nc, nb = len(t), len(t.encode('utf-8'))
    if nc < 1500 or nc > 5200: canh.append(f'độ dài {nc} ký tự')
    if nb > 14500: loi.append(f'{nb} byte > 14500')
    return loi, canh


def main():
    kb = kich_ban()
    ds = [int(x) for x in sys.argv[1:]] or list(range(1, 121))
    tong = 0
    for n in ds:
        loi, canh = soat(n, kb)
